=== FILE: apb_gpio.v ===
// apb_gpio.v
// APB4 GPIO peripheral with interrupts.
// Implements microarchitecture.md for interface_spec.md (rtl/apb-gpio).
//  - Zero wait states: pready tied high, access = psel & penable.
//  - Nine 32-bit registers; bits N and up are held at zero by PINS.
//  - INTR_STATUS is write-1-to-clear; a detection beats a clear.
//  - Synchronous, active-low reset of every flop.

module apb_gpio #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

  // Register indices (paddr[5:2])
  localparam [3:0] IDX_DATA_OUT    = 4'd0;
  localparam [3:0] IDX_DIR         = 4'd1;
  localparam [3:0] IDX_DATA_IN     = 4'd2;
  localparam [3:0] IDX_INTR_RISE   = 4'd3;
  localparam [3:0] IDX_INTR_FALL   = 4'd4;
  localparam [3:0] IDX_INTR_HIGH   = 4'd5;
  localparam [3:0] IDX_INTR_LOW    = 4'd6;
  localparam [3:0] IDX_INTR_ENABLE = 4'd7;
  localparam [3:0] IDX_INTR_STATUS = 4'd8;

  // Bits 0 .. N-1 set: the pins that exist.
  localparam [31:0] PINS = (N >= 32) ? 32'hFFFF_FFFF : ((32'd1 << N) - 32'd1);

  // ------------------------------------------------------------------
  // State
  // ------------------------------------------------------------------
  reg [31:0] data_out_q;
  reg [31:0] dir_q;
  reg [31:0] in_q;
  reg [31:0] in_prev_q;
  reg [31:0] rise_q;
  reg [31:0] fall_q;
  reg [31:0] high_q;
  reg [31:0] low_q;
  reg [31:0] ien_q;
  reg [31:0] status_q;

  // ------------------------------------------------------------------
  // APB decode
  // ------------------------------------------------------------------
  wire       access     = psel & penable;
  wire [3:0] idx        = paddr[5:2];
  wire       upper_zero = ~|paddr[ADDR_WIDTH-1:6];
  wire       mapped     = (paddr[1:0] == 2'b00) & upper_zero & (idx <= IDX_INTR_STATUS);
  wire       wr_en      = access & pwrite & mapped;
  wire       rd_en      = access & ~pwrite & mapped;

  wire we_data_out = wr_en & (idx == IDX_DATA_OUT);
  wire we_dir      = wr_en & (idx == IDX_DIR);
  wire we_rise     = wr_en & (idx == IDX_INTR_RISE);
  wire we_fall     = wr_en & (idx == IDX_INTR_FALL);
  wire we_high     = wr_en & (idx == IDX_INTR_HIGH);
  wire we_low      = wr_en & (idx == IDX_INTR_LOW);
  wire we_ien      = wr_en & (idx == IDX_INTR_ENABLE);
  wire we_status   = wr_en & (idx == IDX_INTR_STATUS);

  // Byte strobes expanded to bits, limited to existing pins.
  wire [31:0] wmask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;

  function [31:0] merge;
    input [31:0] old_v;
    input [31:0] new_v;
    input [31:0] mask_v;
    begin
      merge = (old_v & ~mask_v) | (new_v & mask_v);
    end
  endfunction

  // ------------------------------------------------------------------
  // Input sample, widened to 32 bits with zeros above N
  // ------------------------------------------------------------------
  wire [31:0] in_ext;
  generate
    if (N < 32) begin : g_in_pad
      assign in_ext = {{(32 - N){1'b0}}, gpio_in};
    end else begin : g_in_full
      assign in_ext = gpio_in;
    end
  endgenerate

  // ------------------------------------------------------------------
  // Next-state logic
  // ------------------------------------------------------------------
  wire [31:0] data_out_d = we_data_out ? merge(data_out_q, pwdata, wmask) : data_out_q;
  wire [31:0] dir_d      = we_dir      ? merge(dir_q,      pwdata, wmask) : dir_q;
  wire [31:0] rise_d     = we_rise     ? merge(rise_q,     pwdata, wmask) : rise_q;
  wire [31:0] fall_d     = we_fall     ? merge(fall_q,     pwdata, wmask) : fall_q;
  wire [31:0] high_d     = we_high     ? merge(high_q,     pwdata, wmask) : high_q;
  wire [31:0] low_d      = we_low      ? merge(low_q,      pwdata, wmask) : low_q;
  wire [31:0] ien_d      = we_ien      ? merge(ien_q,      pwdata, wmask) : ien_q;

  wire [31:0] rise_ev  = in_q & ~in_prev_q;
  wire [31:0] fall_ev  = ~in_q & in_prev_q;
  wire [31:0] detected = ((rise_ev & rise_q) | (fall_ev & fall_q)
                         | (in_q & high_q) | (~in_q & low_q)) & PINS;
  wire [31:0] clear    = we_status ? (pwdata & wmask) : 32'd0;
  // Detection ORed last: a detection beats a clear on the same edge.
  wire [31:0] status_d = (status_q & ~clear) | detected;

  // ------------------------------------------------------------------
  // Registers: synchronous active-low reset
  // ------------------------------------------------------------------
  always @(posedge pclk) begin
    if (!presetn) begin
      data_out_q <= 32'd0;
      dir_q      <= 32'd0;
      in_q       <= 32'd0;
      in_prev_q  <= 32'd0;
      rise_q     <= 32'd0;
      fall_q     <= 32'd0;
      high_q     <= 32'd0;
      low_q      <= 32'd0;
      ien_q      <= 32'd0;
      status_q   <= 32'd0;
    end else begin
      data_out_q <= data_out_d;
      dir_q      <= dir_d;
      in_q       <= in_ext;
      in_prev_q  <= in_q;
      rise_q     <= rise_d;
      fall_q     <= fall_d;
      high_q     <= high_d;
      low_q      <= low_d;
      ien_q      <= ien_d;
      status_q   <= status_d;
    end
  end

  // ------------------------------------------------------------------
  // Read data and responses
  // ------------------------------------------------------------------
  reg [31:0] rdata_mux;
  always @* begin
    case (idx)
      IDX_DATA_OUT:    rdata_mux = data_out_q;
      IDX_DIR:         rdata_mux = dir_q;
      IDX_DATA_IN:     rdata_mux = in_q;
      IDX_INTR_RISE:   rdata_mux = rise_q;
      IDX_INTR_FALL:   rdata_mux = fall_q;
      IDX_INTR_HIGH:   rdata_mux = high_q;
      IDX_INTR_LOW:    rdata_mux = low_q;
      IDX_INTR_ENABLE: rdata_mux = ien_q;
      IDX_INTR_STATUS: rdata_mux = status_q;
      default:         rdata_mux = 32'd0;
    endcase
  end

  assign prdata   = rd_en ? rdata_mux : 32'd0;
  assign pready   = 1'b1;
  assign pslverr  = access & (~mapped | (pwrite & (idx == IDX_DATA_IN)));

  assign gpio_out = data_out_q[N-1:0];
  assign gpio_oe  = dir_q[N-1:0];
  assign irq      = |(status_q & ien_q);

`ifdef FORMAL
  // Design-intent assertions (combinational, independent of state).
  always @* begin
    assert (pready == 1'b1);
    if (!access) assert (pslverr == 1'b0);
    if (!rd_en) assert (prdata == 32'd0);
  end
`endif

endmodule
=== END FILE ===
=== FILE: apb_gpio_tb.v ===
`timescale 1ns/1ps

// ----------------------------------------------------------------------
// Reference model of interface_spec.md, written bit by bit with a
// full-address decode, independent of the RTL's structure.
// ----------------------------------------------------------------------
module apb_gpio_ref #(
    parameter integer N = 8
) (
    input  wire        pclk,
    input  wire        presetn,
    input  wire [7:0]  paddr,
    input  wire        psel,
    input  wire        penable,
    input  wire        pwrite,
    input  wire [31:0] pwdata,
    input  wire [3:0]  pstrb,
    input  wire [31:0] gpio_in,
    output reg  [31:0] e_prdata,
    output reg         e_pslverr,
    output wire [31:0] e_out,
    output wire [31:0] e_oe,
    output reg         e_irq
);
  reg [31:0] m_dout, m_dir, m_din, m_prev, m_rise, m_fall, m_high, m_low, m_en, m_stat;
  reg [31:0] n_dout, n_dir, n_din, n_rise, n_fall, n_high, n_low, n_en, n_stat;
  reg [31:0] pin_m, lane_m, det, clr;
  reg        hit;
  reg [3:0]  sel;
  reg        wr;
  integer    b;

  always @* begin
    hit = 1'b1;
    case (paddr)
      8'h00:   sel = 4'd0;
      8'h04:   sel = 4'd1;
      8'h08:   sel = 4'd2;
      8'h0C:   sel = 4'd3;
      8'h10:   sel = 4'd4;
      8'h14:   sel = 4'd5;
      8'h18:   sel = 4'd6;
      8'h1C:   sel = 4'd7;
      8'h20:   sel = 4'd8;
      default: begin hit = 1'b0; sel = 4'd15; end
    endcase
    wr = psel & penable & pwrite & hit;

    n_dout = m_dout;
    n_dir  = m_dir;
    n_rise = m_rise;
    n_fall = m_fall;
    n_high = m_high;
    n_low  = m_low;
    n_en   = m_en;
    clr    = 32'd0;

    for (b = 0; b < 32; b = b + 1) begin
      pin_m[b]  = (b < N);
      lane_m[b] = pin_m[b] & pstrb[b / 8];
      n_din[b]  = pin_m[b] & gpio_in[b];
      if (wr && lane_m[b]) begin
        case (sel)
          4'd0:    n_dout[b] = pwdata[b];
          4'd1:    n_dir[b]  = pwdata[b];
          4'd3:    n_rise[b] = pwdata[b];
          4'd4:    n_fall[b] = pwdata[b];
          4'd5:    n_high[b] = pwdata[b];
          4'd6:    n_low[b]  = pwdata[b];
          4'd7:    n_en[b]   = pwdata[b];
          4'd8:    clr[b]    = pwdata[b];
          default: ;
        endcase
      end
      det[b] = 1'b0;
      if (pin_m[b]) begin
        if (m_rise[b] && m_din[b] && !m_prev[b]) det[b] = 1'b1;
        if (m_fall[b] && !m_din[b] && m_prev[b]) det[b] = 1'b1;
        if (m_high[b] && m_din[b])               det[b] = 1'b1;
        if (m_low[b]  && !m_din[b])              det[b] = 1'b1;
      end
      n_stat[b] = det[b] | (m_stat[b] & ~clr[b]);
    end

    e_prdata  = 32'd0;
    e_pslverr = 1'b0;
    if (psel && penable) begin
      if (!hit || (pwrite && (sel == 4'd2))) begin
        e_pslverr = 1'b1;
      end else if (!pwrite) begin
        case (sel)
          4'd0:    e_prdata = m_dout;
          4'd1:    e_prdata = m_dir;
          4'd2:    e_prdata = m_din;
          4'd3:    e_prdata = m_rise;
          4'd4:    e_prdata = m_fall;
          4'd5:    e_prdata = m_high;
          4'd6:    e_prdata = m_low;
          4'd7:    e_prdata = m_en;
          4'd8:    e_prdata = m_stat;
          default: e_prdata = 32'd0;
        endcase
      end
    end
    e_irq = |(m_stat & m_en);
  end

  always @(posedge pclk) begin
    if (!presetn) begin
      m_dout <= 32'd0; m_dir  <= 32'd0; m_din  <= 32'd0; m_prev <= 32'd0;
      m_rise <= 32'd0; m_fall <= 32'd0; m_high <= 32'd0; m_low  <= 32'd0;
      m_en   <= 32'd0; m_stat <= 32'd0;
    end else begin
      m_dout <= n_dout; m_dir  <= n_dir;  m_din  <= n_din;  m_prev <= m_din;
      m_rise <= n_rise; m_fall <= n_fall; m_high <= n_high; m_low  <= n_low;
      m_en   <= n_en;   m_stat <= n_stat;
    end
  end

  assign e_out = m_dout;
  assign e_oe  = m_dir;
endmodule

// ----------------------------------------------------------------------
// Self-checking testbench: DUTs at N=8 and N=32 on one APB bus.
// ----------------------------------------------------------------------
module apb_gpio_tb;
  localparam [7:0] A_DOUT = 8'h00;
  localparam [7:0] A_DIR  = 8'h04;
  localparam [7:0] A_DIN  = 8'h08;
  localparam [7:0] A_RISE = 8'h0C;
  localparam [7:0] A_FALL = 8'h10;
  localparam [7:0] A_HIGH = 8'h14;
  localparam [7:0] A_LOW  = 8'h18;
  localparam [7:0] A_EN   = 8'h1C;
  localparam [7:0] A_STAT = 8'h20;

  reg         pclk;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  reg  [31:0] pins;

  wire [31:0] prdata8, prdata32;
  wire        pready8, pready32, pslverr8, pslverr32;
  wire [7:0]  gout8, goe8;
  wire [31:0] gout32, goe32;
  wire        irq8, irq32;

  wire [31:0] e_prdata8, e_prdata32, e_out8, e_oe8, e_out32, e_oe32;
  wire        e_err8, e_err32, e_irq8, e_irq32;

  integer passed   = 0;
  integer failed   = 0;
  integer mon_pass = 0;
  integer mon_fail = 0;
  integer i;

  reg [31:0] rd8, rd32;
  reg        err8, err32, rdy8, rdy32;
  reg [7:0]  cur_addr;
  reg [7:0]  a;
  reg [8*64-1:0] nonce;

  apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata8),
    .pready(pready8), .pslverr(pslverr8), .gpio_in(pins[7:0]),
    .gpio_out(gout8), .gpio_oe(goe8), .irq(irq8)
  );

  apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata32),
    .pready(pready32), .pslverr(pslverr32), .gpio_in(pins),
    .gpio_out(gout32), .gpio_oe(goe32), .irq(irq32)
  );

  apb_gpio_ref #(.N(8)) ref8 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .gpio_in(pins),
    .e_prdata(e_prdata8), .e_pslverr(e_err8), .e_out(e_out8), .e_oe(e_oe8), .e_irq(e_irq8)
  );

  apb_gpio_ref #(.N(32)) ref32 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .gpio_in(pins),
    .e_prdata(e_prdata32), .e_pslverr(e_err32), .e_out(e_out32), .e_oe(e_oe32), .e_irq(e_irq32)
  );

  initial pclk = 1'b0;
  always #5 pclk = ~pclk;

  // Continuous comparison against the reference models, mid-cycle.
  always @(negedge pclk) begin
    if (prdata8 !== e_prdata8 || pslverr8 !== e_err8 || pready8 !== 1'b1 ||
        {24'd0, gout8} !== e_out8 || {24'd0, goe8} !== e_oe8 || irq8 !== e_irq8) begin
      mon_fail = mon_fail + 1;
      $error("monitor N=8 t=%0t: prdata %h/%h pslverr %b/%b pready %b out %h/%h oe %h/%h irq %b/%b",
             $time, prdata8, e_prdata8, pslverr8, e_err8, pready8,
             gout8, e_out8, goe8, e_oe8, irq8, e_irq8);
    end else begin
      mon_pass = mon_pass + 1;
    end
    if (prdata32 !== e_prdata32 || pslverr32 !== e_err32 || pready32 !== 1'b1 ||
        gout32 !== e_out32 || goe32 !== e_oe32 || irq32 !== e_irq32) begin
      mon_fail = mon_fail + 1;
      $error("monitor N=32 t=%0t: prdata %h/%h pslverr %b/%b pready %b out %h/%h oe %h/%h irq %b/%b",
             $time, prdata32, e_prdata32, pslverr32, e_err32, pready32,
             gout32, e_out32, goe32, e_oe32, irq32, e_irq32);
    end else begin
      mon_pass = mon_pass + 1;
    end
  end

  // ---------------------------------------------------------------- tasks
  task tick;
    begin
      @(posedge pclk);
      #1;
    end
  endtask

  task chk(input [8*32-1:0] name, input [31:0] got, input [31:0] exp);
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("%0s mismatch (last addr %h, t=%0t): got %h, expected %h",
               name, cur_addr, $time, got, exp);
      end
    end
  endtask

  task chk1(input [8*32-1:0] name, input got, input exp);
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("%0s mismatch (last addr %h, t=%0t): got %b, expected %b",
               name, cur_addr, $time, got, exp);
      end
    end
  endtask

  // One APB transfer. Entered 1 ns after a rising edge; returns 1 ns after
  // the completing edge with the bus idle. Consecutive calls are
  // back-to-back (setup directly after completion).
  task apb_xfer(input wr, input [7:0] addr, input [31:0] data, input [3:0] strb);
    begin
      cur_addr = addr;
      psel     = 1'b1;
      penable  = 1'b0;
      pwrite   = wr;
      paddr    = addr;
      pwdata   = wr ? data : 32'd0;
      pstrb    = wr ? strb : 4'd0;
      tick;
      penable  = 1'b1;
      @(negedge pclk);
      rd8   = prdata8;
      rd32  = prdata32;
      err8  = pslverr8;
      err32 = pslverr32;
      rdy8  = pready8;
      rdy32 = pready32;
      @(posedge pclk);
      #1;
      psel    = 1'b0;
      penable = 1'b0;
      pwrite  = 1'b0;
      pstrb   = 4'd0;
      pwdata  = 32'd0;
      paddr   = 8'd0;
    end
  endtask

  task wr_chk(input [7:0] addr, input [31:0] data, input [3:0] strb, input xerr);
    begin
      apb_xfer(1'b1, addr, data, strb);
      chk1("pslverr write N=8", err8, xerr);
      chk1("pslverr write N=32", err32, xerr);
      chk1("pready write N=8", rdy8, 1'b1);
      chk1("pready write N=32", rdy32, 1'b1);
    end
  endtask

  task rd_chk(input [7:0] addr, input [31:0] x8, input [31:0] x32, input xerr);
    begin
      apb_xfer(1'b0, addr, 32'd0, 4'd0);
      chk("prdata N=8", rd8, x8);
      chk("prdata N=32", rd32, x32);
      chk1("pslverr read N=8", err8, xerr);
      chk1("pslverr read N=32", err32, xerr);
      chk1("pready read N=8", rdy8, 1'b1);
      chk1("pready read N=32", rdy32, 1'b1);
    end
  endtask

  task chk_pins(input [31:0] o8, input [31:0] e8, input [31:0] o32, input [31:0] e32,
                input i8, input i32);
    begin
      chk("gpio_out N=8", {24'd0, gout8}, o8);
      chk("gpio_oe N=8", {24'd0, goe8}, e8);
      chk("gpio_out N=32", gout32, o32);
      chk("gpio_oe N=32", goe32, e32);
      chk1("irq N=8", irq8, i8);
      chk1("irq N=32", irq32, i32);
    end
  endtask

  task rd_all_zero;
    begin
      rd_chk(A_DOUT, 32'd0, 32'd0, 1'b0);
      rd_chk(A_DIR,  32'd0, 32'd0, 1'b0);
      rd_chk(A_DIN,  32'd0, 32'd0, 1'b0);
      rd_chk(A_RISE, 32'd0, 32'd0, 1'b0);
      rd_chk(A_FALL, 32'd0, 32'd0, 1'b0);
      rd_chk(A_HIGH, 32'd0, 32'd0, 1'b0);
      rd_chk(A_LOW,  32'd0, 32'd0, 1'b0);
      rd_chk(A_EN,   32'd0, 32'd0, 1'b0);
      rd_chk(A_STAT, 32'd0, 32'd0, 1'b0);
    end
  endtask

  // ---------------------------------------------------------------- test
  initial begin
    presetn  = 1'b0;
    psel     = 1'b0;
    penable  = 1'b0;
    pwrite   = 1'b0;
    paddr    = 8'd0;
    pwdata   = 32'd0;
    pstrb    = 4'd0;
    pins     = 32'd0;
    cur_addr = 8'd0;
    a        = 8'd0;
    repeat (3) @(posedge pclk);
    #1;
    presetn = 1'b1;
    tick;

    // 1. Reset values
    chk_pins(32'd0, 32'd0, 32'd0, 32'd0, 1'b0, 1'b0);
    rd_all_zero;

    // 2. DATA_OUT with partial strobes and bits above N
    wr_chk(A_DOUT, 32'hA5A5_A5A5, 4'b1111, 1'b0);
    rd_chk(A_DOUT, 32'h0000_00A5, 32'hA5A5_A5A5, 1'b0);
    chk("gpio_out N=8", {24'd0, gout8}, 32'h0000_00A5);
    chk("gpio_out N=32", gout32, 32'hA5A5_A5A5);
    wr_chk(A_DOUT, 32'h5A5A_5A5A, 4'b0101, 1'b0);
    rd_chk(A_DOUT, 32'h0000_005A, 32'hA55A_A55A, 1'b0);
    wr_chk(A_DOUT, 32'h0000_0000, 4'b0000, 1'b0);
    rd_chk(A_DOUT, 32'h0000_005A, 32'hA55A_A55A, 1'b0);
    wr_chk(A_DOUT, 32'hFFFF_FFFF, 4'b1110, 1'b0);
    rd_chk(A_DOUT, 32'h0000_005A, 32'hFFFF_FF5A, 1'b0);

    // 3. DIR
    wr_chk(A_DIR, 32'h0F0F_00F0, 4'b1111, 1'b0);
    rd_chk(A_DIR, 32'h0000_00F0, 32'h0F0F_00F0, 1'b0);
    wr_chk(A_DIR, 32'h1234_5678, 4'b1000, 1'b0);
    rd_chk(A_DIR, 32'h0000_00F0, 32'h120F_00F0, 1'b0);
    wr_chk(A_DIR, 32'h0000_00FF, 4'b0001, 1'b0);
    rd_chk(A_DIR, 32'h0000_00FF, 32'h120F_00FF, 1'b0);
    chk_pins(32'h0000_005A, 32'h0000_00FF, 32'hFFFF_FF5A, 32'h120F_00FF, 1'b0, 1'b0);

    // 4. Interrupt configuration registers (read/write, strobes, bits above N)
    a = A_RISE;
    for (i = 0; i < 5; i = i + 1) begin
      wr_chk(a, 32'hFFFF_FFFF, 4'b1111, 1'b0);
      rd_chk(a, 32'h0000_00FF, 32'hFFFF_FFFF, 1'b0);
      wr_chk(a, 32'h0000_0000, 4'b0011, 1'b0);
      rd_chk(a, 32'h0000_0000, 32'hFFFF_0000, 1'b0);
      wr_chk(a, 32'h00A5_0000, 4'b0100, 1'b0);
      rd_chk(a, 32'h0000_0000, 32'hFFA5_0000, 1'b0);
      wr_chk(a, 32'h0000_0000, 4'b1111, 1'b0);
      rd_chk(a, 32'h0000_0000, 32'h0000_0000, 1'b0);
      a = a + 8'h04;
    end
    // INTR_LOW was enabled with pins low: clear what it set.
    wr_chk(A_STAT, 32'hFFFF_FFFF, 4'b1111, 1'b0);
    rd_chk(A_STAT, 32'd0, 32'd0, 1'b0);
    chk1("irq N=8", irq8, 1'b0);
    chk1("irq N=32", irq32, 1'b0);

    // 5. DATA_IN is read only
    pins = 32'h8100_003C;
    tick;
    rd_chk(A_DIN, 32'h0000_003C, 32'h8100_003C, 1'b0);
    wr_chk(A_DIN, 32'h0000_0000, 4'b1111, 1'b1);
    rd_chk(A_DIN, 32'h0000_003C, 32'h8100_003C, 1'b0);
    rd_chk(A_DOUT, 32'h0000_005A, 32'hFFFF_FF5A, 1'b0);
    rd_chk(A_STAT, 32'd0, 32'd0, 1'b0);
    pins = 32'd0;
    tick;
    tick;
    rd_chk(A_DIN, 32'd0, 32'd0, 1'b0);

    // 6. PSLVERR policy: unmapped and unaligned
    rd_chk(8'h01, 32'd0, 32'd0, 1'b1);
    rd_chk(8'h02, 32'd0, 32'd0, 1'b1);
    rd_chk(8'h03, 32'd0, 32'd0, 1'b1);
    rd_chk(8'h05, 32'd0, 32'd0, 1'b1);
    rd_chk(8'h0E, 32'd0, 32'd0, 1'b1);
    rd_chk(8'h21, 32'd0, 32'd0, 1'b1);
    rd_chk(8'h23, 32'd0, 32'd0, 1'b1);
    rd_chk(8'h24, 32'd0, 32'd0, 1'b1);
    rd_chk(8'h28, 32'd0, 32'd0, 1'b1);
    rd_chk(8'h3C, 32'd0, 32'd0, 1'b1);
    rd_chk(8'h40, 32'd0, 32'd0, 1'b1);
    rd_chk(8'h44, 32'd0, 32'd0, 1'b1);
    rd_chk(8'h80, 32'd0, 32'd0, 1'b1);
    rd_chk(8'hFC, 32'd0, 32'd0, 1'b1);
    rd_chk(8'hFF, 32'd0, 32'd0, 1'b1);
    wr_chk(8'h01, 32'hFFFF_FFFF, 4'b1111, 1'b1);
    wr_chk(8'h40, 32'hFFFF_FFFF, 4'b1111, 1'b1);
    wr_chk(8'h44, 32'hFFFF_FFFF, 4'b1111, 1'b1);
    wr_chk(8'h80, 32'hFFFF_FFFF, 4'b1111, 1'b1);
    wr_chk(8'hC0, 32'hFFFF_FFFF, 4'b1111, 1'b1);
    wr_chk(8'h24, 32'hFFFF_FFFF, 4'b1111, 1'b1);
    wr_chk(8'h5C, 32'hFFFF_FFFF, 4'b1111, 1'b1);
    wr_chk(8'h1D, 32'hFFFF_FFFF, 4'b1111, 1'b1);
    rd_chk(A_DOUT, 32'h0000_005A, 32'hFFFF_FF5A, 1'b0);
    rd_chk(A_DIR,  32'h0000_00FF, 32'h120F_00FF, 1'b0);
    rd_chk(A_EN,   32'd0, 32'd0, 1'b0);

    // 7a. Rising edge, masked; an edge fires once
    wr_chk(A_RISE, 32'h8000_0101, 4'b1111, 1'b0);
    rd_chk(A_RISE, 32'h0000_0001, 32'h8000_0101, 1'b0);
    pins = 32'h8000_0101;
    tick;
    tick;
    rd_chk(A_STAT, 32'h0000_0001, 32'h8000_0101, 1'b0);
    chk1("irq masked N=8", irq8, 1'b0);
    chk1("irq masked N=32", irq32, 1'b0);
    wr_chk(A_STAT, 32'hFFFF_FFFF, 4'b1111, 1'b0);
    tick;
    tick;
    rd_chk(A_STAT, 32'd0, 32'd0, 1'b0);
    pins = 32'd0;
    tick;
    tick;
    rd_chk(A_STAT, 32'd0, 32'd0, 1'b0);
    wr_chk(A_RISE, 32'd0, 4'b1111, 1'b0);

    // 7b. Falling edge; clear honours strobes
    wr_chk(A_FALL, 32'h0000_0202, 4'b1111, 1'b0);
    pins = 32'h0000_0202;
    tick;
    tick;
    rd_chk(A_STAT, 32'd0, 32'd0, 1'b0);
    pins = 32'd0;
    tick;
    tick;
    rd_chk(A_STAT, 32'h0000_0002, 32'h0000_0202, 1'b0);
    wr_chk(A_STAT, 32'h0000_0002, 4'b1111, 1'b0);
    rd_chk(A_STAT, 32'd0, 32'h0000_0200, 1'b0);
    wr_chk(A_STAT, 32'h0000_0200, 4'b0001, 1'b0);
    rd_chk(A_STAT, 32'd0, 32'h0000_0200, 1'b0);
    wr_chk(A_STAT, 32'h0000_0200, 4'b0010, 1'b0);
    rd_chk(A_STAT, 32'd0, 32'd0, 1'b0);
    wr_chk(A_FALL, 32'd0, 4'b1111, 1'b0);

    // 7c. High level: sets again after a clear while held
    wr_chk(A_HIGH, 32'h0004_0004, 4'b1111, 1'b0);
    pins = 32'h0004_0004;
    tick;
    tick;
    rd_chk(A_STAT, 32'h0000_0004, 32'h0004_0004, 1'b0);
    wr_chk(A_STAT, 32'hFFFF_FFFF, 4'b1111, 1'b0);
    rd_chk(A_STAT, 32'h0000_0004, 32'h0004_0004, 1'b0);
    pins = 32'd0;
    tick;
    tick;
    wr_chk(A_STAT, 32'hFFFF_FFFF, 4'b1111, 1'b0);
    rd_chk(A_STAT, 32'd0, 32'd0, 1'b0);
    wr_chk(A_HIGH, 32'd0, 4'b1111, 1'b0);

    // 7d. Low level
    wr_chk(A_LOW, 32'h0000_0808, 4'b1111, 1'b0);
    tick;
    rd_chk(A_STAT, 32'h0000_0008, 32'h0000_0808, 1'b0);
    wr_chk(A_STAT, 32'hFFFF_FFFF, 4'b1111, 1'b0);
    rd_chk(A_STAT, 32'h0000_0008, 32'h0000_0808, 1'b0);
    pins = 32'h0000_0808;
    tick;
    tick;
    wr_chk(A_STAT, 32'hFFFF_FFFF, 4'b1111, 1'b0);
    rd_chk(A_STAT, 32'd0, 32'd0, 1'b0);
    wr_chk(A_LOW, 32'd0, 4'b1111, 1'b0);
    pins = 32'd0;
    tick;
    tick;
    rd_chk(A_STAT, 32'd0, 32'd0, 1'b0);

    // 7e. Both edges enabled, one-cycle pulse
    wr_chk(A_RISE, 32'h0000_0020, 4'b1111, 1'b0);
    wr_chk(A_FALL, 32'h0000_0020, 4'b1111, 1'b0);
    pins = 32'h0000_0020;
    tick;
    pins = 32'd0;
    tick;
    tick;
    tick;
    rd_chk(A_STAT, 32'h0000_0020, 32'h0000_0020, 1'b0);
    wr_chk(A_STAT, 32'h0000_0020, 4'b1111, 1'b0);
    rd_chk(A_STAT, 32'd0, 32'd0, 1'b0);
    wr_chk(A_RISE, 32'd0, 4'b1111, 1'b0);
    wr_chk(A_FALL, 32'd0, 4'b1111, 1'b0);

    // 7f. Clear some pending bits only; interrupt mask
    wr_chk(A_RISE, 32'h8002_0271, 4'b1111, 1'b0);
    pins = 32'h8002_0271;
    tick;
    tick;
    rd_chk(A_STAT, 32'h0000_0071, 32'h8002_0271, 1'b0);
    chk1("irq masked N=8", irq8, 1'b0);
    chk1("irq masked N=32", irq32, 1'b0);
    wr_chk(A_EN, 32'h0000_0001, 4'b1111, 1'b0);
    chk1("irq unmasked N=8", irq8, 1'b1);
    chk1("irq unmasked N=32", irq32, 1'b1);
    wr_chk(A_STAT, 32'h0002_0030, 4'b0001, 1'b0);
    rd_chk(A_STAT, 32'h0000_0041, 32'h8002_0241, 1'b0);
    chk1("irq N=8", irq8, 1'b1);
    chk1("irq N=32", irq32, 1'b1);
    wr_chk(A_STAT, 32'h0000_0000, 4'b1111, 1'b0);
    rd_chk(A_STAT, 32'h0000_0041, 32'h8002_0241, 1'b0);
    wr_chk(A_STAT, 32'h0000_0001, 4'b1111, 1'b0);
    rd_chk(A_STAT, 32'h0000_0040, 32'h8002_0240, 1'b0);
    chk1("irq cleared N=8", irq8, 1'b0);
    chk1("irq cleared N=32", irq32, 1'b0);
    wr_chk(A_EN, 32'h8000_0000, 4'b1000, 1'b0);
    rd_chk(A_EN, 32'h0000_0001, 32'h8000_0001, 1'b0);
    chk1("irq unmask pending N=8", irq8, 1'b0);
    chk1("irq unmask pending N=32", irq32, 1'b1);
    wr_chk(8'h60, 32'hFFFF_FFFF, 4'b1111, 1'b1);
    wr_chk(8'h22, 32'hFFFF_FFFF, 4'b1111, 1'b1);
    rd_chk(A_STAT, 32'h0000_0040, 32'h8002_0240, 1'b0);
    wr_chk(A_STAT, 32'hFFFF_FFFF, 4'b1111, 1'b0);
    rd_chk(A_STAT, 32'd0, 32'd0, 1'b0);
    chk1("irq N=8", irq8, 1'b0);
    chk1("irq N=32", irq32, 1'b0);
    wr_chk(A_EN, 32'd0, 4'b1111, 1'b0);
    pins = 32'd0;
    tick;
    tick;

    // irq timing: pin change before edge E -> status and irq after E+1
    wr_chk(A_EN, 32'h0000_0001, 4'b1111, 1'b0);
    pins = 32'h0000_0001;
    @(negedge pclk);
    chk1("irq before E N=8", irq8, 1'b0);
    chk1("irq before E N=32", irq32, 1'b0);
    tick;
    @(negedge pclk);
    chk1("irq after E N=8", irq8, 1'b0);
    chk1("irq after E N=32", irq32, 1'b0);
    tick;
    @(negedge pclk);
    chk1("irq after E+1 N=8", irq8, 1'b1);
    chk1("irq after E+1 N=32", irq32, 1'b1);
    tick;
    wr_chk(A_STAT, 32'h0000_0001, 4'b1111, 1'b0);
    chk1("irq N=8", irq8, 1'b0);
    chk1("irq N=32", irq32, 1'b0);
    pins = 32'd0;
    tick;
    tick;

    // 7g. A detection beats a clear on the same edge
    pins = 32'h0000_0001;
    tick;
    tick;
    pins = 32'd0;
    tick;
    tick;
    rd_chk(A_STAT, 32'h0000_0001, 32'h0000_0001, 1'b0);
    pins = 32'h0000_0001;                         // sampled at the setup->access edge
    wr_chk(A_STAT, 32'h0000_0001, 4'b1111, 1'b0); // clear lands on the detection edge
    rd_chk(A_STAT, 32'h0000_0001, 32'h0000_0001, 1'b0);
    chk1("irq N=8", irq8, 1'b1);
    chk1("irq N=32", irq32, 1'b1);
    wr_chk(A_STAT, 32'h0000_0001, 4'b1111, 1'b0); // no new edge: clear sticks
    rd_chk(A_STAT, 32'd0, 32'd0, 1'b0);
    pins = 32'd0;
    tick;
    tick;
    wr_chk(A_RISE, 32'd0, 4'b1111, 1'b0);
    wr_chk(A_EN, 32'd0, 4'b1111, 1'b0);

    // 8. Reset again, from a busy state
    wr_chk(A_HIGH, 32'h0000_0001, 4'b1111, 1'b0);
    pins = 32'h0000_0001;
    tick;
    tick;
    wr_chk(A_EN, 32'h0000_0001, 4'b1111, 1'b0);
    chk1("irq pre-reset N=8", irq8, 1'b1);
    chk1("irq pre-reset N=32", irq32, 1'b1);
    presetn = 1'b0;
    tick;
    tick;
    chk_pins(32'd0, 32'd0, 32'd0, 32'd0, 1'b0, 1'b0);
    pins = 32'd0;
    presetn = 1'b1;
    tick;
    chk_pins(32'd0, 32'd0, 32'd0, 32'd0, 1'b0, 1'b0);
    rd_all_zero;
    tick;

    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce,
             passed + mon_pass, failed + mon_fail);
    $finish;
  end
endmodule
